def make_interesting_array(N, A):
    if N <= 2:
        return "-1"

    A.sort()
    result = [0] * N
    result[::2] = A[:N//2]
    result[1::2] = A[N//2:]

    for i in range(1, N):
        if (result[i-1] <= result[i] and result[i] >= result[i+1]) or (result[i-1] >= result[i] and result[i] <= result[i+1]):
            return "-1"

    return ' '.join(map(str, result))

def main():
